import{_ as t,o as i,c as a,ag as d}from"./chunks/framework.DoUXNnsN.js";const k=JSON.parse('{"title":"Modbus-RTU","description":"","frontmatter":{"title":"Modbus-RTU","aliases":["Modbus RTU","RTU","CRC-16","CRC校验","Modbus CRC"],"tags":["工业通信","Modbus"],"status":"ai-draft","sources":["https://en.wikipedia.org/wiki/Modbus","https://www.simplymodbus.ca/FC03.htm","https://www.simplymodbus.ca/FC16.htm","https://www.simplymodbus.ca/FC05.htm","https://industrialmonitordirect.com/blogs/knowledgebase/configuring-modbus-rtu-serial-communication-settings","基于模型知识"],"updated":"2026-10-21T00:00:00.000Z","order":4},"headers":[],"relativePath":"70-工业通信与自动化/Modbus/Modbus-RTU.md","filePath":"70-工业通信与自动化/Modbus/Modbus-RTU.md"}'),e={name:"70-工业通信与自动化/Modbus/Modbus-RTU.md"};function l(o,s,h,n,r,p){return i(),a("div",null,[...s[0]||(s[0]=[d(`<blockquote class="callout-warn"><p>⚠ 待核对：本篇&quot;没有校验位时要用 2 个停止位&quot;一句来自二手资料对规范原文的转述，我没有打开规范原文核实，请对照设备手册或规范核对。其余内容（帧结构、CRC、静默间隔）已对照维基百科和 simplymodbus.ca，并且 CRC 部分我用代码实际计算验证过。</p></blockquote><blockquote><p>本篇是 <a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus">Modbus</a> 入门路径的第 4 篇。读完你应该能：说出一帧 RTU 报文由哪几部分组成；自己计算 CRC 校验；理解&quot;静默间隔&quot;为什么重要；配置串口参数；排查串口通信故障。</p></blockquote><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p>Modbus RTU 是 Modbus 跑在<strong>串口</strong>（常见的是 RS-485）上的形式：用二进制紧凑地发送，靠 CRC 校验发现传输错误，靠&quot;静默间隔&quot;划分一帧的开始和结束。</p><h2 id="先修知识" tabindex="-1">先修知识 <a class="header-anchor" href="#先修知识" aria-label="Permalink to &quot;先修知识&quot;">​</a></h2><ul><li><a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus">Modbus</a>、<a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus功能码">Modbus功能码</a>：知道一条请求里有什么。</li><li><a href="/Encyclopedia/70-工业通信与自动化/串口通信">串口通信</a>：知道波特率、校验位、停止位是什么。简单说：串口一位一位地发数据，双方必须约定好发送速度和格式。</li><li><a href="/Encyclopedia/10-计算机基础/数据表示/十六进制">十六进制</a>。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>串口线本身只负责一位一位地传，它不知道&quot;一条消息从哪开始到哪结束&quot;，也不知道传输中有没有被干扰弄错了。RTU 用两个办法补上：</p><ol><li><strong>静默间隔</strong>：一帧报文连续发送，帧与帧之间必须留一段&quot;没有数据&quot;的空白，接收方靠空白知道一帧结束了。</li><li><strong>CRC 校验</strong>：发送方把整帧算出一个 2 字节的校验值附在最后，接收方重新算一遍，对不上就丢弃这一帧，避免误把干扰当成数据。</li></ol><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="物理层-rs-485-是什么" tabindex="-1">物理层：RS-485 是什么 <a class="header-anchor" href="#物理层-rs-485-是什么" aria-label="Permalink to &quot;物理层：RS-485 是什么&quot;">​</a></h3><p>工业现场最常见的是 RS-485：两根线（常标 A 和 B），用两线之间的<strong>电压差</strong>表示 0 和 1，抗干扰能力强，传输距离可达上千米（低速时）。它是<strong>半双工</strong>的：同一时刻只能一方发送，所以必须是&quot;主站问，从站答&quot;，不能同时说话。所有设备并联挂在同一条总线上，线路两端各接一个终端电阻（常见 120 Ω）来减少信号反射。这些是行业常见做法，以具体设备手册为准。</p><h3 id="串口参数-双方必须完全一致" tabindex="-1">串口参数：双方必须完全一致 <a class="header-anchor" href="#串口参数-双方必须完全一致" aria-label="Permalink to &quot;串口参数：双方必须完全一致&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>常见取值</th><th>说明</th></tr></thead><tbody><tr><td>波特率</td><td>9600（典型）、19200、38400…</td><td>每秒传多少位</td></tr><tr><td>数据位</td><td>8</td><td>RTU 固定 8 位</td></tr><tr><td>校验位</td><td>偶校验（规范默认）、奇校验、无</td><td>简单的奇偶检查</td></tr><tr><td>停止位</td><td>1（有校验时）</td><td>无校验时规范要求用 2 个停止位（见开头的核对提示）</td></tr></tbody></table><p>RTU 每个字节发送时占 <strong>11 位</strong>：1 个起始位 + 8 个数据位（低位先发）+ 1 个校验位 + 1 个停止位。<strong>主站和所有从站的这几个参数必须完全相同</strong>，只要有一个不同，就是&quot;完全没有回应&quot;或者&quot;全是错帧&quot;。</p><h3 id="一帧长什么样" tabindex="-1">一帧长什么样 <a class="header-anchor" href="#一帧长什么样" aria-label="Permalink to &quot;一帧长什么样&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| 从站地址 | 功能码 | 数据 (0–252 字节) | CRC (2 字节) |</span></span>
<span class="line"><span>|  1 字节  | 1 字节 |                   | 低字节在前    |</span></span></code></pre></div><ul><li>从站地址 + 功能码 + 数据，合起来对应 <a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus功能码">Modbus功能码</a> 里讲的 PDU 加上地址；</li><li>整帧最长 256 字节（1 + 253 + 2）；</li><li>例子：<code>11 03 006B 0003 7687</code>。</li></ul><h3 id="静默间隔-靠-安静-划分帧" tabindex="-1">静默间隔：靠&quot;安静&quot;划分帧 <a class="header-anchor" href="#静默间隔-靠-安静-划分帧" aria-label="Permalink to &quot;静默间隔：靠&quot;安静&quot;划分帧&quot;">​</a></h3><ul><li><strong>帧与帧之间</strong>至少要有 <strong>3.5 个字符时间</strong>的静默，表示一帧结束；</li><li><strong>帧内相邻两个字符</strong>之间的停顿不能超过 <strong>1.5 个字符时间</strong>，超过就认为这一帧已经出错。</li></ul><p>&quot;字符时间&quot;= 发一个字符（11 位）要多久，取决于波特率：</p><table tabindex="0"><thead><tr><th>波特率</th><th>1 个字符</th><th>3.5 个字符（帧间静默）</th></tr></thead><tbody><tr><td>9600</td><td>11 ÷ 9600 ≈ 1.146 ms</td><td>≈ 4.01 ms</td></tr><tr><td>19200</td><td>11 ÷ 19200 ≈ 0.573 ms</td><td>≈ 2.005 ms</td></tr></tbody></table><p>波特率高于 19200 时，规范改用固定值：帧间静默 1.750 ms，字符间隔 750 μs（来自维基百科对规范的转述）。<strong>实际意义</strong>：用 PC 发送时，软件要保证一帧的字节是连着发出去的，中间不能被系统调度卡住几毫秒，否则从站会把一帧当成两帧，直接丢掉。这就是为什么 USB 转串口在 Windows 下偶尔会&quot;偶发性通信失败&quot;。</p><h3 id="crc-16-校验-怎么算" tabindex="-1">CRC-16 校验：怎么算 <a class="header-anchor" href="#crc-16-校验-怎么算" aria-label="Permalink to &quot;CRC-16 校验：怎么算&quot;">​</a></h3><p>Modbus 用的是 CRC-16-MODBUS。算法很机械，不需要理解数学原理也能用：</p><ol><li>先设一个 16 位变量 <code>crc = 0xFFFF</code>；</li><li>对帧里的每个字节（不含 CRC 本身）：把字节和 <code>crc</code> 的低 8 位异或；</li><li>然后重复 8 次：如果 <code>crc</code> 的最低位是 1，就把 <code>crc</code> 右移一位再和 <code>0xA001</code> 异或；否则只右移一位；</li><li>全部字节处理完，<code>crc</code> 就是结果；</li><li><strong>发送时低字节在前</strong>：结果是 <code>0x8776</code>，线上发的是 <code>76 87</code>。</li></ol><p>Python 实现（我已实际运行验证）：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> crc16_modbus</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(data: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bytes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) -&gt; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    crc </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">FFFF</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> data:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        crc </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">^=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> _ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> range</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            crc </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (crc </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">^</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">A001</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> crc </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> else</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> crc </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> crc</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> with_crc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(payload: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bytes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) -&gt; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bytes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    c </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> crc16_modbus(payload)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> payload </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> bytes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([c </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">FF</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, c </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">])   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 低字节在前</span></span></code></pre></div><p>用网上已知的帧验证，我计算出来全部一致（&quot;线上顺序&quot;就是发送顺序）：</p><table tabindex="0"><thead><tr><th>帧（不含 CRC）</th><th>计算得到</th><th>线上顺序</th><th>来源给出的 CRC</th></tr></thead><tbody><tr><td><code>11 03 006B 0003</code></td><td>0x8776</td><td><code>76 87</code></td><td>7687</td></tr><tr><td><code>11 03 06 AE41 5652 4340</code></td><td>0xAD49</td><td><code>49 AD</code></td><td>49AD</td></tr><tr><td><code>11 10 0001 0002 04 000A 0102</code></td><td>0xF0C6</td><td><code>C6 F0</code></td><td>C6F0</td></tr><tr><td><code>11 10 0001 0002</code></td><td>0x9812</td><td><code>12 98</code></td><td>1298</td></tr><tr><td><code>11 05 00AC FF00</code></td><td>0x8B4E</td><td><code>4E 8B</code></td><td>4E8B</td></tr><tr><td><code>01 04 02 FFFF</code></td><td>0x80B8</td><td><code>B8 80</code></td><td>B880</td></tr></tbody></table><p>接收方的做法是：把**整帧（包括 CRC）**一起算，结果为 0 就说明没出错；或者重算前面部分，和收到的 CRC 比较。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><p><strong>实验 1：自己算 CRC</strong></p><ol><li>把上面的 <code>crc16_modbus</code> 和 <code>with_crc</code> 保存成 <code>crc_lab.py</code>，末尾加一行： <code>print(with_crc(bytes.fromhex(&quot;0103000000&quot; + &quot;0A&quot;)).hex(&quot; &quot;))</code></li><li>运行 <code>python crc_lab.py</code>，你会得到 <code>01 03 00 00 00 0a c5 cd</code>。这就是&quot;读 1 号从站从地址 0 开始的 10 个寄存器&quot;的完整 RTU 请求帧。</li><li>把其中一个字节改掉（例如 <code>0A</code> 改成 <code>0B</code>），再看 CRC 变成什么，体会&quot;改一个字节，CRC 就完全不同&quot;。</li></ol><p><strong>实验 2（有硬件时）</strong>：如果你有 USB 转 RS-485 适配器和一台 Modbus 设备，可以用 Modbus Poll、QModMaster 这类调试软件（具体选择以官网为准）：</p><ol><li>把适配器的 A、B 线接到设备的 A、B（不同厂家的 A/B 标注不统一，接反了互换一下即可，不会损坏设备）；</li><li>在软件里把波特率、校验位、停止位设成和设备一样；</li><li>填从站地址、功能码 03、起始地址和数量，点读取；</li><li>对照软件里显示的发送和接收字节，用本篇的方法逐字节解释。</li></ol><h2 id="常见坑与排查" tabindex="-1">常见坑与排查 <a class="header-anchor" href="#常见坑与排查" aria-label="Permalink to &quot;常见坑与排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>最可能的原因</th></tr></thead><tbody><tr><td>完全没有回应</td><td>波特率/校验位/停止位不一致；A/B 接反；从站地址写错；从站没上电</td></tr><tr><td>能通，但隔一会儿就失败</td><td>干扰、线太长、没接终端电阻；USB 转串口驱动在发送时打断了字节连续性</td></tr><tr><td>全是 CRC 错误</td><td>波特率或校验位设错，数据其实在串口上被&quot;读歪&quot;了</td></tr><tr><td>多台从站时只有一台能通</td><td>地址重复；总线上的设备数超过驱动能力；没接好终端电阻</td></tr><tr><td>主站发了请求，从站回得很慢</td><td>主站超时设置过短，从站处理慢；看设备手册的响应时间</td></tr><tr><td>同一条总线上换了设备就不通</td><td>新设备的串口参数和其他设备不一样，需要统一</td></tr><tr><td>一个字节都收不到，但接线正确</td><td>半双工方向控制：发送完必须及时切回接收，否则会吃掉回应</td></tr></tbody></table><h2 id="练习题与答案" tabindex="-1">练习题与答案 <a class="header-anchor" href="#练习题与答案" aria-label="Permalink to &quot;练习题与答案&quot;">​</a></h2><ol><li>波特率 9600，8E1，发 1 个字符需要多久？帧间最少静默多久？ <strong>答</strong>：每字符 11 位，11 ÷ 9600 ≈ 1.146 ms；3.5 个字符 ≈ 4.01 ms。</li><li>请求 <code>01 03 00 00 00 0A</code> 的 CRC 是多少？线上怎么发？ <strong>答</strong>：CRC 是 <code>0xCDC5</code>，线上顺序 <code>C5 CD</code>，整帧 <code>01 03 00 00 00 0A C5 CD</code>。</li><li>9600 波特率下，请求帧 <code>11 03 006B 0003 7687</code>（共 8 字节）发出需要多久？ <strong>答</strong>：8 × 11 = 88 位，88 ÷ 9600 ≈ 9.17 ms。</li><li>上一题的回应帧 <code>11 03 06 AE41 5652 4340 49AD</code> 有多少字节？发出要多久？ <strong>答</strong>：1+1+1+6+2 = 11 字节，11 × 11 = 121 位，121 ÷ 9600 ≈ 12.6 ms。所以仅这一问一答，传输就要约 22 ms（还不含两端的处理时间和静默间隔），轮询几十个设备时要把这个时间估进去。</li><li>主站发 <code>01 03 0064 0001</code> 读一个不存在的地址，从站回异常响应 <code>01 83 02</code>。这帧的 CRC 是什么？ <strong>答</strong>：<code>0xF1C0</code>，线上顺序 <code>C0 F1</code>，整帧 <code>01 83 02 C0 F1</code>。</li></ol><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RTU = 串口上的 Modbus：地址 + 功能码 + 数据 + CRC（低字节在前）。</li><li>每字节 11 位；帧间静默 ≥ 3.5 字符时间，字符间隔 ≤ 1.5 字符时间。</li><li>主站和所有从站的波特率、校验位、停止位必须完全一致。</li><li>没有回应先查：参数、A/B 线、地址、终端电阻、供电。</li><li>半双工，一问一答，总线上的轮询时间要累加着算。</li></ul><h2 id="相关词条" tabindex="-1">相关词条 <a class="header-anchor" href="#相关词条" aria-label="Permalink to &quot;相关词条&quot;">​</a></h2><p><a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus">Modbus</a>、<a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus功能码">Modbus功能码</a>、<a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus-TCP">Modbus-TCP</a>、<a href="/Encyclopedia/70-工业通信与自动化/串口通信">串口通信</a>、<a href="/Encyclopedia/70-工业通信与自动化/PLC">PLC</a></p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>维基百科 Modbus 词条（含帧结构和时序）：<a href="https://en.wikipedia.org/wiki/Modbus" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/Modbus</a></li><li>Simply Modbus 读保持寄存器页（带 CRC 的完整例子）：<a href="https://www.simplymodbus.ca/FC03.htm" target="_blank" rel="noreferrer">https://www.simplymodbus.ca/FC03.htm</a></li></ul>`,46)])])}const u=t(e,[["render",l]]);export{k as __pageData,u as default};
